param([string]$Runtime='win-x64',[Parameter(Mandatory=$true)][string]$CertificateThumbprint,[string]$Version='0.1.0')
$ErrorActionPreference='Stop';$Version=$Version.TrimStart('v');dotnet publish ..\src\GManager.Client.Service -c Release -r $Runtime --self-contained -p:Version=$Version -o ..\artifacts\service;dotnet publish ..\src\GManager.Client.Shell -c Release -r $Runtime --self-contained -p:Version=$Version -o ..\artifacts\shell;$settings=Get-Content ..\artifacts\service\appsettings.json -Raw|ConvertFrom-Json;$settings.Client.Version=$Version;$settings|ConvertTo-Json -Depth 5|Set-Content ..\artifacts\service\appsettings.json -Encoding utf8
$certificate=Get-Item "Cert:\CurrentUser\My\$CertificateThumbprint";Get-ChildItem ..\artifacts -Recurse -Filter *.exe|ForEach-Object{signtool sign /sha1 $CertificateThumbprint /fd SHA256 /tr http://timestamp.digicert.com /td SHA256 $_.FullName};Get-ChildItem ..\artifacts -Recurse -Filter *.ps1|ForEach-Object{Set-AuthenticodeSignature $_.FullName $certificate -TimestampServer http://timestamp.digicert.com|Out-Null};Get-ChildItem . -Filter *.ps1|Where-Object Name -ne 'publish.ps1'|ForEach-Object{Set-AuthenticodeSignature $_.FullName $certificate -TimestampServer http://timestamp.digicert.com|Out-Null}
Copy-Item update-client.ps1,support-bundle.ps1 ..\artifacts -Force;Compress-Archive ..\artifacts\service, ..\artifacts\shell, ..\artifacts\update-client.ps1, ..\artifacts\support-bundle.ps1, install-service.ps1, uninstall-service.ps1 ..\artifacts\GManager.Client.zip -Force
$hash=(Get-FileHash ..\artifacts\GManager.Client.zip -Algorithm SHA256).Hash.ToLowerInvariant();@{version=$Version;sha256=$hash;signingSubject=$certificate.Subject}|ConvertTo-Json|Set-Content ..\artifacts\GManager.Client.manifest.json -Encoding utf8;Set-AuthenticodeSignature ..\artifacts\GManager.Client.manifest.json $certificate -TimestampServer http://timestamp.digicert.com|Out-Null
